-- 59 Windswept Meadow: the wind is all in the material (meadow_sway, a
-- VertexOffset graph); this only sets how strong it is - the `wind`
-- parameter of every blade and flower, scaled per row. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/59-windswept-meadow.scene"
local ROWS = { { n = 150, wind = 9.0 }, { n = 170, wind = 13.0 }, { n = 180, wind = 18.0 }, { n = 170, wind = 24.0 } }
local FLOWERS = { 0, 16, 22, 28 }
local captions = true
local strength = 1.0
local status
local plants = {}   -- { entity, row wind }

function init(entity)
    status = Entity.find_by_name("Status")
    for k, row in ipairs(ROWS) do
        for i = 1, row.n do
            local e = Entity.find_by_name("Grass" .. k .. "_" .. i)
            if e then plants[#plants + 1] = { e, row.wind } end
        end
        for i = 1, FLOWERS[k] do
            local e = Entity.find_by_name("Flower" .. k .. "_" .. i)
            if e then plants[#plants + 1] = { e, row.wind } end
        end
    end
end

local function blow()
    for _, p in ipairs(plants) do Material.set_float(p[1], "wind", p[2] * strength) end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Up") then strength = math.min(2.5, strength + 0.25); blow() end
    if Input.is_key_just_pressed("Down") then strength = math.max(0.0, strength - 0.25); blow() end
    if status then
        UI.set_text(status, strength == 0 and "a still afternoon"
            or ("wind " .. math.floor(strength * 100 + 0.5) .. "%   " .. #plants .. " plants, one material"))
    end
end
